from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    # Build Aho-Corasick automaton
    trie = [{}]
    bad = [False]

    for word in banned:
        u = 0
        for ch in word:
            if ch not in trie[u]:
                trie[u][ch] = len(trie)
                trie.append({})
                bad.append(False)
            u = trie[u][ch]
        bad[u] = True

    fail = [0] * len(trie)
    q = deque()
    for ch in alphabet:
        if ch in trie[0]:
            v = trie[0][ch]
            fail[v] = 0
            q.append(v)
        else:
            trie[0][ch] = 0

    while q:
        u = q.popleft()
        for ch in alphabet:
            if ch in trie[u]:
                v = trie[u][ch]
                fail[v] = trie[fail[u]][ch]
                if bad[fail[v]]:
                    bad[v] = True
                q.append(v)
            else:
                trie[u][ch] = trie[fail[u]][ch]

    # Map non-banned states to matrix indices
    good_idx = {}
    for u in range(len(trie)):
        if not bad[u]:
            good_idx[u] = len(good_idx)

    k = len(good_idx)
    if k == 0 or 0 not in good_idx:
        return 0

    mat = [[0] * k for _ in range(k)]
    for u, i in good_idx.items():
        for ch in alphabet:
            v = trie[u][ch]
            if v in good_idx:
                mat[i][good_idx[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * k for _ in range(k)]
        for i in range(k):
            ai = a[i]
            ri = res[i]
            for j in range(k):
                aij = ai[j]
                if aij:
                    bj = b[j]
                    for l in range(k):
                        ri[l] = (ri[l] + aij * bj[l]) % MOD
        return res

    # Binary exponentiation: compute vec * mat^n where vec = [1, 0, ..., 0]
    vec = [0] * k
    vec[0] = 1
    power = n
    base = mat

    while power > 0:
        if power & 1:
            new_vec = [0] * k
            for i in range(k):
                vi = vec[i]
                if vi:
                    bi = base[i]
                    for j in range(k):
                        new_vec[j] = (new_vec[j] + vi * bi[j]) % MOD
            vec = new_vec
        power >>= 1
        if power > 0:
            base = mat_mul(base, base)

    return sum(vec) % MOD
